/**
 * Better Auth + Cloudflare Email Service integration.
 *
 * Two transports, one interface:
 *
 *   // Inside a Cloudflare Worker — uses the send_email binding (zero latency, no API key)
 *   const email = cloudflareEmail.workers({ binding: env.EMAIL, from: "..." });
 *
 *   // Anywhere else — uses the Cloudflare REST API
 *   const email = cloudflareEmail.api({ accountId: "...", apiToken: "...", from: "..." });
 *
 * Both return the same object shape — spread `email.config` into betterAuth()
 * and wire plugin callbacks identically.
 *
 * Generated by quickback.dev
 */

// ---------------------------------------------------------------------------
// Workers binding types
// ---------------------------------------------------------------------------

/** Native Workers binding sender/recipient address. */
export type WorkersEmailAddress = string | EmailAddress;

/** Native Workers binding message builder (the final send() overload). */
export type WorkersEmailMessage = Parameters<SendEmail["send"]>[0];

// ---------------------------------------------------------------------------
// REST API types (the HTTP API intentionally has different field names)
// ---------------------------------------------------------------------------

export type RestEmailAddress = string | { address: string; name: string };

export interface RestEmailMessage {
  to: string | string[];
  from: RestEmailAddress;
  subject: string;
  html?: string;
  text?: string;
  cc?: string | string[];
  bcc?: string | string[];
  reply_to?: RestEmailAddress;
  headers?: Record<string, string>;
  attachments?: RestEmailAttachment[];
}

export type RestEmailAttachment = RestInlineAttachment | RestStandardAttachment;

export interface RestInlineAttachment {
  filename: string;
  content: string;
  type: string;
  disposition: "inline";
  content_id: string;
}

export interface RestStandardAttachment {
  filename: string;
  content: string;
  type: string;
  disposition: "attachment";
}

export interface RestEmailSendResult {
  delivered: string[];
  permanent_bounces: string[];
  queued: string[];
}

// ---------------------------------------------------------------------------
// Transport interface
// ---------------------------------------------------------------------------

interface RenderedEmail {
  to: string;
  subject: string;
  html: string;
  text: string;
}

export interface EmailTransport<TMessage, TResult> {
  send(message: TMessage): Promise<TResult>;
  sendRendered(message: RenderedEmail): Promise<TResult>;
}

// ---------------------------------------------------------------------------
// Template types
// ---------------------------------------------------------------------------

export interface TemplateData {
  appName: string;
  url?: string;
  token?: string;
  otp?: string;
  email?: string;
  userName?: string;
  /** Link/code lifetime in seconds, as configured on the sending plugin. */
  expiresIn?: number;
}

export interface OrgInvitationData {
  appName: string;
  inviterName: string;
  organizationName: string;
  invitationUrl: string;
  role: string;
}

export type TemplateFn = (data: TemplateData) => { subject: string; html: string; text: string };
export type OrgInvitationTemplateFn = (data: OrgInvitationData) => { subject: string; html: string; text: string };

export interface Templates {
  verifyEmail?: TemplateFn;
  resetPassword?: TemplateFn;
  changeEmail?: TemplateFn;
  deleteAccount?: TemplateFn;
  magicLink?: TemplateFn;
  otp?: TemplateFn;
  organizationInvitation?: OrgInvitationTemplateFn;
}

// ---------------------------------------------------------------------------
// Shared options (transport-agnostic)
// ---------------------------------------------------------------------------

interface SharedOptions {
  /** Application name shown in email templates. Default: "Our App". */
  appName?: string;

  /** Override default email templates per type. */
  templates?: Templates;

  /**
   * Anchor a delivery promise to the request lifecycle. Generated Workers
   * pass a scheduler backed by executionCtx.waitUntil().
   */
  schedule?: EmailDeliveryScheduler;
}

export type EmailDeliveryScheduler = (delivery: Promise<unknown>) => Promise<void>;

// ---------------------------------------------------------------------------
// Workers transport options
// ---------------------------------------------------------------------------

export interface WorkersOptions extends SharedOptions {
  /** Default "from" address. Uses the native Workers { email, name } shape. */
  from: WorkersEmailAddress;

  /** The send_email binding, or a function that returns it (for singleton auth). */
  binding: SendEmail | (() => SendEmail);
}

// ---------------------------------------------------------------------------
// REST API transport options
// ---------------------------------------------------------------------------

export interface ApiOptions extends SharedOptions {
  /** Default "from" address. REST object form uses { address, name }. */
  from: RestEmailAddress;

  /** Cloudflare Account ID. */
  accountId: string;

  /** Cloudflare API Token with email send permissions. */
  apiToken: string;

  /** Override the base URL. Default: "https://api.cloudflare.com/client/v4" */
  baseUrl?: string;
}

