// ---------------------------------------------------------------------------
// Transport implementations
// ---------------------------------------------------------------------------

function createWorkersTransport(opts: WorkersOptions): EmailTransport<WorkersEmailMessage, EmailSendResult> {
  return {
    async send(message) {
      const binding = typeof opts.binding === "function" ? opts.binding() : opts.binding;
      return binding.send(message);
    },
    async sendRendered(message) {
      const binding = typeof opts.binding === "function" ? opts.binding() : opts.binding;
      return binding.send({ ...message, from: opts.from });
    },
  };
}

function createApiTransport(opts: ApiOptions): EmailTransport<RestEmailMessage, RestEmailSendResult> {
  const baseUrl = opts.baseUrl ?? "https://api.cloudflare.com/client/v4";
  const url = `${baseUrl}/accounts/${opts.accountId}/email/sending/send`;

  return {
    async send(message) {
      const res = await fetch(url, {
        method: "POST",
        headers: {
          Authorization: `Bearer ${opts.apiToken}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify(message),
      });

      if (!res.ok) {
        const body = await res.text();
        throw new Error(`Cloudflare Email API error (${res.status}): ${body}`);
      }

      const json = (await res.json()) as {
        success: boolean;
        result?: RestEmailSendResult;
        errors?: Array<{ code: number; message: string }>;
      };

      if (!json.success) {
        const msg = json.errors?.map((e) => e.message).join(", ") ?? "Unknown error";
        throw new Error(`Cloudflare Email API error: ${msg}`);
      }

      return json.result ?? { delivered: [], permanent_bounces: [], queued: [] };
    },
    async sendRendered(message) {
      return this.send({ ...message, from: opts.from });
    },
  };
}

// ---------------------------------------------------------------------------
// Build the Better Auth integration from any transport
// ---------------------------------------------------------------------------

export interface CloudflareEmailResult<TMessage, TResult> {
  /** Spread into betterAuth() to wire up core email callbacks automatically. */
  config: {
    emailVerification: {
      sendVerificationEmail: (data: { user: { email: string; name?: string }; url: string; token: string }, request?: Request) => Promise<void>;
      sendOnSignUp: true;
    };
    emailAndPassword: {
      sendResetPassword: (data: { user: { email: string; name?: string }; url: string; token: string }, request?: Request) => Promise<void>;
    };
    user: {
      changeEmail: {
        enabled: true;
        sendChangeEmailConfirmation: (data: { user: { email: string; name?: string }; newEmail: string; url: string; token: string }, request?: Request) => Promise<void>;
      };
      deleteUser: {
        enabled: true;
        sendDeleteAccountVerification: (data: { user: { email: string; name?: string }; url: string; token: string }, request?: Request) => Promise<void>;
      };
    };
  };

  /** For magicLink() plugin. */
  sendMagicLink: (data: { email: string; url: string; token: string; metadata?: Record<string, unknown>; expiresIn?: number }) => Promise<void>;

  /** For emailOTP() plugin. */
  sendVerificationOTP: (data: { email: string; otp: string; type: string; expiresIn?: number }) => Promise<void>;

  /** For organization() plugin invitation emails. */
  sendOrganizationInvitation: (data: { email: string; inviterName: string; organizationName: string; invitationUrl: string; role: string }) => Promise<void>;

  /** Send an arbitrary email through the underlying transport. */
  sendRaw: (message: TMessage) => Promise<TResult>;
}

function reportDeliveryFailure<T>(delivery: Promise<T>): Promise<T> {
  return delivery.catch(() => {
    console.error(JSON.stringify({ level: "error", event: "auth.email.delivery_failed" }));
    throw new Error("Auth email delivery failed");
  });
}

function build<TMessage, TResult>(
  transport: EmailTransport<TMessage, TResult>,
  shared: SharedOptions,
): CloudflareEmailResult<TMessage, TResult> {
  const appName = shared.appName ?? "Our App";
  const t = { ...defaultTemplates, ...shared.templates };

  function deliver(to: string, rendered: { subject: string; html: string; text: string }): Promise<void> {
    const observed = reportDeliveryFailure(
      transport.sendRendered({ to, ...rendered }),
    ).then(() => undefined);
    return shared.schedule ? shared.schedule(observed) : observed;
  }

  const sendVerificationEmail = async (
    data: { user: { email: string; name?: string }; url: string; token: string },
    _request?: Request,
  ) => deliver(data.user.email, t.verifyEmail({ appName, url: data.url, token: data.token, userName: data.user.name }));

  const sendResetPassword = async (
    data: { user: { email: string; name?: string }; url: string; token: string },
    _request?: Request,
  ) => deliver(data.user.email, t.resetPassword({ appName, url: data.url, token: data.token, userName: data.user.name }));

  const sendChangeEmailConfirmation = async (
    data: { user: { email: string; name?: string }; newEmail: string; url: string; token: string },
    _request?: Request,
  ) => deliver(data.newEmail, t.changeEmail({ appName, url: data.url, token: data.token }));

  const sendDeleteAccountVerification = async (
    data: { user: { email: string; name?: string }; url: string; token: string },
    _request?: Request,
  ) => deliver(data.user.email, t.deleteAccount({ appName, url: data.url, token: data.token }));

  const sendMagicLink = async (
    data: { email: string; url: string; token: string; metadata?: Record<string, unknown>; expiresIn?: number },
  ) => deliver(data.email, t.magicLink({ appName, url: data.url, token: data.token, email: data.email, expiresIn: data.expiresIn }));

  const sendVerificationOTP = async (
    data: { email: string; otp: string; type: string; expiresIn?: number },
  ) => deliver(data.email, t.otp({ appName, otp: data.otp, email: data.email, expiresIn: data.expiresIn }));

  const sendOrganizationInvitation = async (
    data: { email: string; inviterName: string; organizationName: string; invitationUrl: string; role: string },
  ) => deliver(data.email, t.organizationInvitation({ appName, ...data }));

  return {
    config: {
      emailVerification: { sendVerificationEmail, sendOnSignUp: true },
      // No 'enabled' here: the generated auth options own that switch. Setting
      // it would re-enable password sign-in for projects that turned it off
      // (account.auth.password: false), since the generator emits no
      // emailAndPassword block for a disabled provider and the merge would
      // fall through to this default.
      emailAndPassword: { sendResetPassword },
      user: {
        changeEmail: { enabled: true, sendChangeEmailConfirmation },
        deleteUser: { enabled: true, sendDeleteAccountVerification },
      },
    },
    sendMagicLink,
    sendVerificationOTP,
    sendOrganizationInvitation,
    sendRaw: (message) => reportDeliveryFailure(transport.send(message)),
  };
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

export const cloudflareEmail = {
  /**
   * Use inside a Cloudflare Worker — sends via the \`send_email\` binding.
   * Zero network hop, no API key needed.
   */
  workers(opts: WorkersOptions): CloudflareEmailResult<WorkersEmailMessage, EmailSendResult> {
    return build(createWorkersTransport(opts), opts);
  },

  /**
   * Use from any runtime (Node.js, Bun, Deno, Vercel, etc.) — sends via
   * the Cloudflare Email Service REST API.
   */
  api(opts: ApiOptions): CloudflareEmailResult<RestEmailMessage, RestEmailSendResult> {
    return build(createApiTransport(opts), opts);
  },
};

